function External({ href, children }: { href: string; children: React.ReactNode }) { return <a href={href} target="_blank" rel="noreferrer">{children}</a>; }
function Brand() { return <a className="brand" href="/" aria-label="AgentOS home"><img src="/assets/agentlogo.webp" alt="" /><span>Agent<span>OS</span></span></a>; }
function Header() { return <header className="nav-shell subpage-nav"><Brand /><nav aria-label="Main navigation"><div className="nav-links"><a href="/product">Product</a><a href="/download">Download</a><a href="/solutions/solo-founders">Solutions</a><a href="/docs">Resources</a><a href="/#pricing">Pricing</a><a href="/about">Company</a></div></nav><a href="/download" className="button button--small nav-cta">Download Desktop <b>→</b></a></header>; }
function Footer() { const groups: readonly [string, readonly LinkItem[]][] = [["Product", [["Overview", "/product"], ["Features", "/features"], ["Download Desktop", "/download"], ["Pricing", "/#pricing"], ["Integrations", "/integrations"], ["Changelog", "/changelog"]]], ["Solutions", [["Solo Founders", "/solutions/solo-founders"], ["Automation Agencies", "/solutions/automation-agencies"], ["Startup Teams", "/solutions/startup-teams"], ["Web3 & Communities", "/solutions/web3-communities"]]], ["Resources", [["Documentation", "/docs"], ["Deployment Guide", "/deployment-guide"], ["OpenClaw Setup", "/openclaw-setup"], ["Agent Templates", "/templates"], ["FAQ", "/faq"], ["Support", "/support"]]], ["Company", [["About AgentOS", "/about"], ["GitHub", github, true], ["Contact", "/contact"], ["Security", "/security"], ["Privacy Policy", "/privacy"], ["Terms of Service", "/terms"]]]]; return <footer className="footer page-pad subpage-footer"><div className="footer-brand"><Brand /><p>The AI workforce platform to build,<br />run, and scale digital workers.</p><div className="socials" aria-label="AgentOS social links"><External href="https://sapienx.app/">◉</External><External href="https://t.me/sapienapp">◌</External><External href="https://x.com/sapienapp">𝕏</External><External href="https://www.linkedin.com/company/sapienxapp/">in</External><External href={github}>◒</External></div></div>{groups.map(([name, links]) => <nav className="footer-links" aria-label={`${name} links`} key={name}><h4>{name}</h4>{links.map(([label, href, external]) => external ? <External key={label} href={href}>{label}</External> : <a key={label} href={href}>{label}</a>)}</nav>)}<div className="footer-credit"><span>© 2026 AgentOS. All rights reserved.</span><strong>Designed and built by AI agents, powered by AgentOS.</strong><i>✦</i></div></footer>; }
function Hero({ eyebrow, title, summary, image, primary = ["Deploy AgentOS", deploy, true], secondary = ["Read the documentation", "/docs"] as LinkItem }: { eyebrow: string; title: string; summary: string; image?: string; primary?: LinkItem; secondary?: LinkItem }) { const action = (item: LinkItem, className: string) => item[2] ? <External href={item[1]}><span className={className}>{item[0]} <b>→</b></span></External> : <a href={item[1]} className={className}>{item[0]} <b>→</b></a>; return <section className="subpage-hero page-pad"><div><span className="eyebrow pill">{eyebrow}</span><h1>{title}</h1><p>{summary}</p><div className="hero-actions">{action(primary, "button")}{action(secondary, "button button--ghost")}</div></div><div className={`subpage-hero-visual ${image?.includes("cutouts") ? "is-worker" : ""}`}>{image ? <img src={image} alt="" /> : <div className="architecture-mini"><b>AgentOS</b><span>OpenClaw Gateway</span><span>Models, tools and channels</span></div>}</div></section>; }
function FinalCta({ title = "Ready to build your AI workforce?", copy = "Start with one workspace, a clear role and a concrete first task.", action = ["Deploy AgentOS", deploy, true] as LinkItem }: { title?: string; copy?: string; action?: LinkItem }) { return <section className="final-cta page-pad"><div className="cta-panel"><div><h2>{title}</h2><p>{copy}</p></div>{action[2] ? <External href={action[1]}><span className="button footer-offer-cta">{action[0]} <b>→</b></span></External> : <a className="button footer-offer-cta" href={action[1]}>{action[0]} <b>→</b></a>}<div className="cta-video" aria-hidden="true"><video autoPlay muted loop playsInline preload="metadata"><source src="/assets/footer-loop.webm" type="video/webm" /></video></div></div></section>; }
function LinkRow({ links }: { links: readonly LinkItem[] }) { return <div className="resource-links">{links.map(([label, href, external]) => external ? <External key={label} href={href}>{label}</External> : <a key={label} href={href}>{label} <span aria-hidden="true">→</span></a>)}</div>; }

function Solutions({ data }: { data: (typeof solutionData)[string] }) { const team = workers.filter(w => data.team.includes(w.name)); return <><Hero eyebrow={data.eyebrow} title={data.title} summary={data.summary} image={data.image} secondary={["Explore templates", "/templates"]} /><section className="page-pad solution-block"><span className="eyebrow">THE OPERATING PROBLEM</span><h2>Make the recurring work easier to see and supervise.</h2><div className="three-grid">{data.problems.map(([title, text], i) => <article key={title}><span>0{i + 1}</span><h3>{title}</h3><p>{text}</p></article>)}</div></section><section className="page-pad team-section"><div className="section-heading"><span className="eyebrow">A PRACTICAL STARTER TEAM</span><h2>Roles with a defined purpose and review point.</h2></div><div className="template-grid">{team.map(w => <article key={w.name}><img src={w.image} alt="" /><div><span>{w.role}</span><h3>{w.name}</h3><p>{w.purpose}</p></div></article>)}</div></section><section className="page-pad workflow-panel"><span className="eyebrow">EXAMPLE WORKFLOW</span><ol>{data.workflow.map((step, i) => <li key={step}><b>{String(i + 1).padStart(2, "0")}</b>{step}</li>)}</ol></section><section className="page-pad capability-section"><div className="section-heading"><span className="eyebrow">RELEVANT AGENTOS CAPABILITIES</span><h2>Use the product around real operating work.</h2></div><div className="capability-list">{data.capabilities.map(([title, text]) => <article key={title}><h3>{title}</h3><p>{text}</p></article>)}</div><p className="content-note">{data.note}</p><LinkRow links={data.links} /></section><FinalCta title="Start with a small, reviewable operating loop." copy="Design the first worker around work you already understand, then extend it only after you can inspect the result." /></>; }

function Docs() { const groups: readonly [string, string, readonly LinkItem[]][] = [["Start here", "Choose an installation path, verify the local runtime, and create a first workspace around a concrete deliverable.", [["AgentOS Quickstart", quickstart, true], ["Deployment Guide", "/deployment-guide"], ["OpenClaw Setup", "/openclaw-setup"]]], ["Build and organize", "Learn how workspaces, worker roles, files, memory, policies, models and tasks fit together in the operator experience.", [["Product overview", "/product"], ["Worker templates", "/templates"], ["FAQ", "/faq"]]], ["Operate safely", "Use diagnostics, health and compatibility information to understand what the connected runtime can do. Unsupported capabilities should remain visible rather than assumed.", [["Security", "/security"], ["Support", "/support"], ["OpenClaw documentation", openclawDocs, true]]]]; return <><Hero eyebrow="RESOURCES / DOCUMENTATION" title="Documentation for setting up and operating AgentOS." summary="This is a practical hub for the current AgentOS product. Use the Quickstart for supported installation commands, the deployment guide for Railway, and OpenClaw documentation for underlying runtime behavior." image="/assets/screens/07-agents-overview.webp" primary={["Open Quickstart", quickstart, true]} /><section className="page-pad docs-hub">{groups.map(([title, text, links]) => <article key={title}><span className="eyebrow">AGENTOS GUIDE</span><h2>{title}</h2><p>{text}</p><LinkRow links={links} /></article>)}</section><section className="page-pad docs-callout"><h2>What this site does—and does not—document</h2><p>AgentOS organizes workspaces, workers, tasks, context, model access and operational visibility. OpenClaw remains the source of truth for Gateway execution, sessions, channels and runtime capabilities. For the current installation commands and version compatibility, use the official Quickstart and repository documentation.</p><LinkRow links={[["Open AgentOS repository", github, true], ["Read OpenClaw documentation", openclawDocs, true], ["Read Railway documentation", railwayDocs, true]]} /></section><FinalCta title="Set up one real workspace first." copy="The fastest learning path is a scoped workspace, a ready model, one worker and one reviewable task." action={["Read the Quickstart", quickstart, true]} /></>; }

function DeploymentGuide() { const steps: readonly [string, string][] = [["1. Before deployment", "Use the published Railway template for the supported hosted path. You will need a Railway account, an initial administrator password, and a model-provider key before real work can run. Railway infrastructure and selected model-provider usage are billed separately."], ["2. Deploy the published template", "The AgentOS Railway path runs AgentOS and a pinned OpenClaw Gateway in one service. The template provisions a persistent `/data` volume and generates internal AgentOS and OpenClaw tokens. The only required operator input is the initial administrator password."], ["3. Protect and sign in", "Open the generated Railway domain and sign in with the initial administrator credentials. The initial password creates the protected account only when no Instance Protection state exists; changing the deployment variable later does not reset the account."], ["4. Verify the deployment", "Use Railway’s deployment and application logs to confirm the service starts and its healthcheck passes. Railway healthchecks validate deployment readiness; they are not continuous monitoring. A service with an attached volume can have brief downtime during redeployment."], ["5. Preserve the runtime state", "The published template uses `/data` for persistent AgentOS and OpenClaw state across redeploys. Do not remove or replace the volume without understanding the data you are discarding. Railway volumes are mounted at runtime, not during build or pre-deploy steps."], ["6. Connect a ready model", "Use AgentOS Setup Center to connect a provider and verify that a model is ready. AgentOS uses your provider keys; model usage is billed by the provider, separately from Railway infrastructure."], ["7. Create the first operating loop", "Create a workspace, configure one digital worker with a clear role and context, assign a scoped task, then inspect the output and runtime state before adding schedules or more access."], ["8. Update deliberately", "Use the project’s update preflight and compatibility information before updating OpenClaw. AgentOS currently expects OpenClaw 2026.6.8 or newer; run `agentos doctor --deep` when preparing a trusted local environment. For Railway updates, review deploy logs and retain the volume." ]]; return <><Hero eyebrow="RESOURCES / DEPLOYMENT GUIDE" title="Deploy AgentOS on Railway with the runtime and data boundaries understood." summary="The published AgentOS template is the supported Railway path. It combines the application and a pinned OpenClaw Gateway in one service, uses a persistent volume, and keeps the Gateway on container loopback." primary={["Deploy on Railway", deploy, true]} secondary={["Read Railway volumes docs", "https://docs.railway.com/volumes", true]} /><section className="page-pad guide-layout"><aside><b>Deployment checklist</b><a href="#before">Before deployment</a><a href="#verify">Verify deployment</a><a href="#storage">Persistent storage</a><a href="#model">Connect a model</a><a href="#updates">Updates</a></aside><div>{steps.map(([title, text], i) => <section key={title} id={i === 0 ? "before" : i === 3 ? "verify" : i === 4 ? "storage" : i === 5 ? "model" : i === 7 ? "updates" : undefined}><span className="eyebrow">DEPLOYMENT</span><h2>{title}</h2><p>{text}</p></section>)}<div className="guide-warning"><b>Keep secrets out of logs and issue reports.</b><span>Use Railway variables and AgentOS setup controls for credentials. Never paste provider keys, tokens or browser-session material into public GitHub issues.</span></div><LinkRow links={[["AgentOS Quickstart", quickstart, true], ["Railway logs documentation", "https://docs.railway.com/observability/logs", true], ["Get deployment help", "/support"]]} /></div></section><FinalCta title="Ready to deploy a controlled first workspace?" copy="Start with the published template, one provider, and a small task you can inspect end to end." action={["Deploy on Railway", deploy, true]} /></>; }

function OpenClawSetup() { return <><Hero eyebrow="RESOURCES / OPENCLAW" title="Understand the runtime underneath the AgentOS operating layer." summary="AgentOS is the human control surface for workspaces, workers, tasks and supervision. OpenClaw is the Gateway-based runtime that owns agent execution, sessions, models, channels, tools and browser capabilities." primary={["Read OpenClaw docs", openclawDocs, true]} secondary={["Read AgentOS Quickstart", quickstart, true]} /><section className="page-pad architecture-section"><span className="eyebrow">RESPONSIBILITY BOUNDARIES</span><div className="architecture-flow"><article><b>Human operator</b><span>Sets direction, reviews outputs and handles consequential decisions.</span></article><i>→</i><article><b>AgentOS</b><span>Organizes workers and workspaces, dispatches work, presents state and diagnostics.</span></article><i>→</i><article><b>OpenClaw Gateway</b><span>Owns runtime execution, sessions, models, channels, tools and supported capabilities.</span></article><i>→</i><article><b>Connected resources</b><span>User-selected providers, accounts, integrations, channels and browser runtime.</span></article></div></section><section className="page-pad capability-section"><div className="section-heading"><span className="eyebrow">WHAT TO EXPECT</span><h2>Gateway-first, with explicit limits.</h2></div><div className="capability-list"><article><h3>Available through AgentOS</h3><p>AgentOS can connect to a live Gateway, project real state, organize worker and workspace configuration, and expose runtime health, compatibility and supported methods.</p></article><article><h3>Available through OpenClaw</h3><p>Gateway execution, sessions, channels, automations, model access and browser profiles are runtime capabilities. Their availability depends on the configured Gateway and provider setup.</p></article><article><h3>Advanced or incomplete behavior</h3><p>Accounts and browser profiles are an MVP bridge; typed browser-profile dispatch is not yet exposed by OpenClaw. Account rules that require approval remain blocked until approval dispatch exists.</p></article></div></section><section className="page-pad docs-callout"><h2>Hosted and local runtime considerations</h2><p>In the documented Railway deployment, the Gateway stays on container loopback and the supervisor manages its lifecycle. For a deliberately remote operator setup, AgentOS blocks remote Gateway URLs by default unless explicitly enabled; use HTTPS, authentication and exact trusted origins. Do not expose source or package installs publicly without an appropriate network boundary and monitoring.</p><LinkRow links={[["OpenClaw documentation", openclawDocs, true], ["Read security guidance", "/security"], ["Deployment Guide", "/deployment-guide"]]} /></section><FinalCta title="Use runtime diagnostics before assigning real work." copy="A ready model, a reachable Gateway and a scoped workspace are the minimum useful starting point." action={["Read the Quickstart", quickstart, true]} /></>; }

function Templates() { const templates = [...workers, { name: "Support Worker", role: "Support", image: "/assets/workers/cutouts/operator.png", purpose: "Prepares triage summaries and routes questions with relevant context.", setup: "Define escalation conditions, approved sources and where final replies are reviewed.", review: "A human owns customer commitments and sensitive responses." }, { name: "Community Operator", role: "Community", image: "/assets/workers/cutouts/guardian.png", purpose: "Prepares channel summaries, content drafts and escalation notes.", setup: "Connect only approved surfaces and define public-action boundaries.", review: "Approve public posts, moderation and governance-sensitive actions." }]; return <><Hero eyebrow="RESOURCES / WORKER TEMPLATES" title="Start with a role definition, not an unreviewed automation." summary="These setup cards are manual starting points based on the worker concepts used across AgentOS. They are not one-click installations: choose the model, instructions, access and review path in your own workspace." image="/assets/workers/cutouts/builder.png" primary={["Read worker setup", quickstart, true]} secondary={["Explore solutions", "/solutions/solo-founders"]} /><section className="page-pad template-directory">{templates.map(worker => <article key={worker.name}><img src={worker.image} alt="" /><div><span className="eyebrow">{worker.role}</span><h2>{worker.name}</h2><p>{worker.purpose}</p><dl><div><dt>Suggested setup</dt><dd>{worker.setup}</dd></div><div><dt>Human review</dt><dd>{worker.review}</dd></div></dl><a className="button button--ghost" href="/docs">View setup guidance <b>→</b></a></div></article>)}</section><section className="page-pad docs-callout"><h2>What a useful worker definition includes</h2><p>AgentOS workers can be created from role presets—including worker, setup, browser, monitoring and custom—or built from scratch. Give every worker a role, clear operating instructions, model access, workspace context and a defined escalation path. Availability of tools, browser capability and channels depends on the connected OpenClaw runtime.</p><LinkRow links={[["Solo founder workflow", "/solutions/solo-founders"], ["Agency workflow", "/solutions/automation-agencies"], ["OpenClaw setup", "/openclaw-setup"]]} /></section><FinalCta title="Create your first worker manually and deliberately." copy="A narrow role and one measurable deliverable are more useful than a broad template with uncontrolled access." action={["Open AgentOS Quickstart", quickstart, true]} /></>; }

function FAQ() { const categories: readonly [string, readonly [string, string, LinkItem?][]][] = [["AgentOS basics", [["What is AgentOS?", "AgentOS is an open-source operating layer for building and running teams of digital workers. It organizes workspaces, context, tasks, model access and human supervision around the OpenClaw runtime.", ["Product overview", "/product"]], ["Is AgentOS self-hosted?", "AgentOS supports a trusted local operator setup and an explicitly configured hosted deployment. The published Railway template is a documented hosted path.", ["Deployment Guide", "/deployment-guide"]]]], ["Deployment and billing", [["Why is Railway used?", "Railway provides the published template path for running AgentOS and its pinned OpenClaw Gateway together with a persistent volume. You can also use the local installer for a trusted operator machine.", ["Railway guide", "/deployment-guide"]], ["What do I pay for?", "Railway infrastructure usage is billed by Railway. Model usage is billed separately by the provider you connect. AgentOS is designed for bring-your-own-key provider access.", ["Railway pricing and docs", railwayDocs, true]]]], ["Models, data and runtime", [["Can I use my own provider keys?", "Yes. Connect a model provider through AgentOS Setup Center and verify a ready model before dispatching work. Keep provider credentials out of public logs and issue reports.", ["OpenClaw setup", "/openclaw-setup"]], ["Where is state stored on Railway?", "The published template uses a persistent `/data` volume for AgentOS and OpenClaw state across redeploys. The specific data processed by models, accounts and connected services is also subject to those providers’ configurations and policies.", ["Security", "/security"]], ["Can workers use browser automation?", "Browser profiles and account targets can be surfaced through the OpenClaw runtime. The current integration is an MVP bridge and typed browser-profile dispatch is not yet exposed by OpenClaw.", ["Runtime capabilities", "/openclaw-setup"]]]], ["Operations and troubleshooting", [["What happens after a restart?", "Railway can restart a failed service according to its configured restart policy. With the published volume in place, persisted AgentOS and OpenClaw state survives redeploys; inspect deployment logs and runtime health after recovery.", ["Railway troubleshooting", "https://docs.railway.com/deployments/troubleshooting/slow-deployments", true]], ["How do I diagnose a local setup?", "Use `agentos status` and `agentos doctor --deep` from a trusted local environment. Check model readiness, Gateway reachability and authentication before assigning real work.", ["Quickstart", quickstart, true]], ["Which capabilities are planned or blocked?", "AgentOS keeps unsupported controls visible. Account access rules requiring approval are intentionally blocked until approval dispatch exists; do not treat them as a completed feature.", ["Support", "/support"]]]]]; return <><Hero eyebrow="RESOURCES / FAQ" title="Straight answers for deployment, runtime and control." summary="These answers reflect the current AgentOS repository and Quickstart. Follow the linked guides when you need deployment instructions or provider-specific details." primary={["Open the Quickstart", quickstart, true]} /><section className="page-pad faq-page categorized-faq">{categories.map(([category, items]) => <section key={category}><span className="eyebrow">{category}</span>{items.map(([question, answer, link]) => <details key={question}><summary>{question}<span>+</span></summary><p>{answer}</p>{link && <LinkRow links={[link]} />}</details>)}</section>)}</section><FinalCta title="Need a deeper answer?" copy="Use the deployment guide for Railway, OpenClaw setup for runtime concerns, and Support for the right escalation path." action={["Visit Support", "/support"]} /></>; }

function Support() { const cards: readonly [string, string, readonly LinkItem[]][] = [["Product documentation", "Use setup and product guides before opening an issue; they cover the supported installation paths, workspace setup and runtime boundaries.", [["Documentation hub", "/docs"], ["AgentOS Quickstart", quickstart, true], ["FAQ", "/faq"]]], ["Railway deployment help", "For template deployment, domains, logs, volumes, restarts and healthchecks, use the deployment guide alongside Railway’s official documentation.", [["Deployment Guide", "/deployment-guide"], ["Railway documentation", railwayDocs, true]]], ["OpenClaw runtime help", "For Gateway behavior, provider configuration and runtime capabilities, start with the OpenClaw documentation. Keep AgentOS focused on the operating workflow around that runtime.", [["OpenClaw Setup", "/openclaw-setup"], ["OpenClaw docs", openclawDocs, true]]], ["Open-source issues", "Use GitHub issues for reproducible AgentOS bugs and contributions. Include safe steps, expected behavior and redacted logs; never publish tokens or credentials.", [["Open AgentOS issues", issueUrl, true], ["Open repository", github, true]]], ["Security concerns", "Use the repository’s security reporting feature if available. Do not disclose sensitive vulnerabilities in a public issue or community channel.", [["Repository security reporting", securityUrl, true], ["Security overview", "/security"]]], ["General contact", "This site does not operate a ticket form or promise a response time. Use the public project and community routes for the type of request you have.", [["Contact options", "/contact"], ["AgentOS Telegram", "https://t.me/sapienapp", true]]]]; return <><Hero eyebrow="RESOURCES / SUPPORT" title="Choose the support path that matches the problem." summary="AgentOS is an open-source project. Documentation, GitHub, Railway and OpenClaw each cover different parts of the operating stack, so this page helps direct you without promising a ticketing service that does not exist." primary={["Browse documentation", "/docs"]} secondary={["Open GitHub issues", issueUrl, true]} /><section className="page-pad support-grid">{cards.map(([title, text, links]) => <article key={title}><h2>{title}</h2><p>{text}</p><LinkRow links={links} /></article>)}</section><FinalCta title="Start with the evidence." copy="A clear description, safe logs and the exact deployment or runtime context make it easier to resolve a real issue." action={["Open GitHub issues", issueUrl, true]} /></>; }

function About() { return <><Hero eyebrow="COMPANY / ABOUT" title="We are building the operating system for digital workforces." summary="AgentOS exists because operating multiple AI agents across real projects, accounts, files, schedules and approvals is an organizational problem—not simply a prompt-writing problem." image="/assets/screens/01-mission-control.webp" primary={["Explore the product", "/product"]} secondary={["Open the repository", github, true]} /><section className="page-pad prose-sections"><article><span className="eyebrow">WHY AGENTOS</span><h2>Digital workers need an operating environment.</h2><p>In the AgentOS model, a useful digital worker has a defined role, goals, context, memory, policies, tools and model access. Workspaces give those workers a persistent place to operate, rather than treating each task as an isolated conversation.</p></article><article><span className="eyebrow">HUMAN CONTROL</span><h2>Supervision is part of the product.</h2><p>AgentOS is designed to let a human operator inspect execution, transcripts, outputs, token usage, files, health and failures. Workers can prepare work and carry out configured tasks; people remain responsible for direction, approvals and consequential action.</p></article><article><span className="eyebrow">OWNERSHIP</span><h2>Infrastructure and model choice belong to the operator.</h2><p>AgentOS supports local-first use and an explicitly configured hosted deployment. It uses bring-your-own-key provider access, while the documented Railway template keeps AgentOS and a pinned OpenClaw Gateway together with persistent state.</p></article><article><span className="eyebrow">OPEN FOUNDATION</span><h2>AgentOS is built around OpenClaw, not reduced to it.</h2><p>OpenClaw is the Gateway runtime and source of truth for execution, sessions, models, channels and automations. AgentOS is the human operating layer that organizes workers and workspaces, presents live state and translates operational decisions into supported runtime actions.</p></article></section><section className="page-pad docs-callout"><h2>The direction: practical teams, not fictional autonomy.</h2><p>The product is being built to turn individual agents into a coherent, reviewable digital team. Unsupported controls remain visible, and degraded or fallback paths should be explicit rather than hidden.</p><LinkRow links={[["Read Security", "/security"], ["Read OpenClaw Setup", "/openclaw-setup"], ["View the GitHub repository", github, true]]} /></section><FinalCta title="Build the first operating loop." copy="Choose a real project, give one worker a bounded job, and keep a person accountable for the outcome." /></>; }

function Contact() { const paths: readonly [string, string, readonly LinkItem[]][] = [["Product and deployment questions", "Start with the Quickstart and documentation. For public product discussion, use the AgentOS project and community links.", [["AgentOS Quickstart", quickstart, true], ["AgentOS Telegram", "https://t.me/sapienapp", true]]], ["Open-source issues", "Use GitHub for reproducible bugs, feature discussion and contributions. Include redacted diagnostic details and the expected behavior.", [["Open GitHub issues", issueUrl, true], ["Open repository", github, true]]], ["Security disclosure", "Do not use a public issue for sensitive vulnerability details. Use the repository’s security reporting route if it is available.", [["Repository security reporting", securityUrl, true], ["Security overview", "/security"]]], ["General inquiry", "There is no form on this site because it would not send messages to a verified support system. Use the public project or community channel instead.", [["AgentOS Telegram", "https://t.me/sapienapp", true], ["Support hub", "/support"]]]]; return <><Hero eyebrow="COMPANY / CONTACT" title="Find the right public path for your question." summary="AgentOS does not use a form that silently discards messages. Choose documentation, GitHub, community or security reporting based on the kind of request you have." primary={["Visit Support", "/support"]} secondary={["Open GitHub", github, true]} /><section className="page-pad support-grid">{paths.map(([title, text, links]) => <article key={title}><h2>{title}</h2><p>{text}</p><LinkRow links={links} /></article>)}</section><FinalCta title="Bring the right context to the right channel." copy="For issues, share safe reproduction steps. For deployment, include the relevant Railway or runtime context without exposing secrets." action={["Open support hub", "/support"]} /></>; }

function Security() { const principles: readonly [string, string][] = [["Operator-controlled deployment", "AgentOS supports trusted local operator machines and an explicitly configured hosted deployment. The documented Railway path runs the application and Gateway in one persistent service."], ["Gateway boundary", "The published Railway deployment keeps the OpenClaw Gateway on container loopback. Remote Gateway URLs are blocked by default in AgentOS unless explicitly enabled."], ["Bring your own keys", "Model credentials are supplied by the operator and provider access is configured in the deployment. Sensitive values are redacted from diagnostics and compatibility reports where supported."], ["Authentication and origins", "The packaged launcher generates an API token and starts with authentication. Remote write access is disabled by default; intentionally remote operator deployments require authentication, HTTPS and exact trusted origins."], ["Runtime visibility", "AgentOS can expose Gateway health, compatibility, auth state, supported capabilities, sessions and runtime data. Visibility is not a claim of complete audit logging or formal compliance."], ["Limits that remain visible", "Approval-required account rules are blocked until approval dispatch exists. Browser and account access are an MVP bridge, and typed browser-profile dispatch is not yet exposed by OpenClaw."]]; return <><Hero eyebrow="COMPANY / SECURITY" title="Your workforce, your infrastructure, your control surface." summary="AgentOS is designed for trusted operator environments and explicit hosted configuration. Security depends on how you deploy it, which resources you connect and how you manage credentials, network access and human review." image="/assets/workers/cutouts/guardian.png" primary={["Read deployment guidance", "/deployment-guide"]} secondary={["Read repository security policy", securityUrl, true]} /><section className="page-pad architecture-section"><span className="eyebrow">DATA AND CONTROL FLOW</span><div className="architecture-flow"><article><b>User</b><span>Provides direction, reviews sensitive actions and manages deployment access.</span></article><i>→</i><article><b>AgentOS workspace</b><span>Organizes workers, context, tasks and the operator view.</span></article><i>→</i><article><b>OpenClaw Gateway</b><span>Runs supported agent execution and connects runtime services.</span></article><i>→</i><article><b>User-selected resources</b><span>Models, accounts, tools, channels, integrations and browser runtime.</span></article></div></section><section className="page-pad security-grid">{principles.map(([title, text]) => <article key={title}><h2>{title}</h2><p>{text}</p></article>)}</section><section className="page-pad docs-callout"><h2>Responsibilities and limitations</h2><p>Operators are responsible for access policies, provider credentials, the security of connected accounts, workspace file access and their hosting environment. Railway volumes persist data at runtime; protect and back up the environment appropriately. AgentOS does not claim SOC 2, ISO 27001, HIPAA, SAML, SCIM, complete RBAC, immutable audit logs or a security SLA.</p><LinkRow links={[["Privacy Policy draft", "/privacy"], ["Terms draft", "/terms"], ["OpenClaw documentation", openclawDocs, true]]} /></section><FinalCta title="Secure the deployment before expanding access." copy="Use a trusted environment, a ready model, minimal account scope and a review step for consequential work." action={["Open deployment guide", "/deployment-guide"]} /></>; }

function Legal({ type }: { type: "privacy" | "terms" }) { const isPrivacy = type === "privacy"; const sections = isPrivacy ? [["Draft status", "This is a working draft, not approved legal advice. Legal review is required before it is treated as a privacy policy or used for a live service."], ["Self-hosted and hosted deployments", "AgentOS can run on an operator-controlled machine or through an explicitly configured host such as Railway. The deployment operator determines the infrastructure, account settings and data configuration for that instance."], ["Third-party services", "A deployment may send information to selected model providers, connected accounts, channels, browser services and infrastructure providers. Their own terms and privacy policies apply. Bring-your-own-key use does not make AgentOS responsible for those providers’ processing."], ["Logs, retention and responsibilities", "The current product can expose operational and runtime data. The operator is responsible for configuring retention, backups, access and deletion practices for their own deployment. This website does not state a universal retention period or data residency commitment."], ["Contact", "Use the public project and support routes for product questions. Do not submit credentials or security-sensitive details in public issues."]] : [["Draft status", "This is a working draft, not approved legal advice or final terms. Legal review is required before publication or reliance."], ["Product and deployment", "AgentOS is open-source software for building and operating digital workers. Operators may deploy it locally or through their chosen infrastructure provider, and are responsible for that deployment’s access, configuration and costs."], ["Third-party services and keys", "Model providers, Railway and any connected accounts or integrations are separate services with their own terms. Operators supply and manage their own credentials and remain responsible for provider usage charges."], ["Acceptable use and supervision", "Operators must use the software lawfully, protect credentials, respect third-party terms and keep humans responsible for consequential decisions. AgentOS does not promise uninterrupted availability, a security SLA or that every runtime capability is supported."], ["Updates and open-source components", "AgentOS is built around OpenClaw and other open-source components. Operators should review compatibility and deployment changes before updates, particularly where persistent data or connected accounts are involved."], ["Contact", "Use the public repository and support routes for product questions. Do not send sensitive security reports through public issues."]]; return <><section className="legal-hero page-pad"><span className="eyebrow">COMPANY / LEGAL</span><h1>{isPrivacy ? "Privacy Policy" : "Terms of Service"}</h1><p>Draft for legal review · Last updated July 24, 2026</p></section><article className="legal-page"><aside><b>On this page</b>{sections.map(([title]) => <a key={title} href={`#${title.toLowerCase().replaceAll(" ", "-")}`}>{title}</a>)}</aside><div>{/* Legal review required before this draft is treated as approved legal terms. */}{sections.map(([title, text]) => <section key={title} id={title.toLowerCase().replaceAll(" ", "-")}><h2>{title}</h2><p>{text}</p></section>)}<LinkRow links={[["Support", "/support"], ["Security", "/security"], ["Open AgentOS repository", github, true]]} /></div></article></>; }

function Integrations() { const all = [["OpenAI", "Model provider", "Available when configured in your AgentOS and OpenClaw environment.", "Configured"], ["Anthropic", "Model provider", "Available when configured in your AgentOS and OpenClaw environment.", "Configured"], ["Gemini", "Model provider", "Available when configured in your AgentOS and OpenClaw environment.", "Configured"], ["xAI", "Model provider", "Available when configured in your AgentOS and OpenClaw environment.", "Configured"], ["Telegram", "Channel", "A workspace surface supported through OpenClaw where configured.", "Runtime-dependent"], ["Discord", "Channel", "A workspace surface supported through OpenClaw where configured.", "Runtime-dependent"], ["Slack", "Channel", "A workspace surface supported through OpenClaw where configured.", "Runtime-dependent"], ["Browser profiles", "Browser", "An MVP bridge through the underlying runtime; typed browser-profile dispatch is not yet exposed.", "Experimental"]] as const; const [query, setQuery] = useState(""); const shown = useMemo(() => all.filter(x => x.join(" ").toLowerCase().includes(query.toLowerCase())), [query]); return <><Hero eyebrow="PRODUCT / INTEGRATIONS" title="Connect the resources your workforce actually needs." summary="Model providers, channels and browser capability are configured through the connected runtime. This directory describes connection types represented in the current AgentOS product—not a claim that every resource is active in every deployment." image="/assets/screens/08-agent-menu.webp" primary={["Read OpenClaw setup", "/openclaw-setup"]} /><section className="page-pad integration-directory"><label>Search connection types<input value={query} onChange={e => setQuery(e.target.value)} placeholder="Models, channels or browser capability" /></label><div className="integration-grid">{shown.map(([name, category, copy, status]) => <article key={name}><span>{category}</span><i className={status === "Experimental" ? "status-beta" : "status-community"}>{status}</i><h2>{name}</h2><p>{copy}</p></article>)}</div><p className="content-note">Connection availability depends on your configured provider keys, Gateway capabilities, scopes and account policies. AgentOS makes unsupported or degraded paths visible rather than representing them as ready.</p></section><FinalCta title="Connect a model before connecting everything else." copy="A single ready provider and a scoped task are the clearest way to verify a new deployment." action={["Read deployment guide", "/deployment-guide"]} /></>; }

function Changelog() { return <><Hero eyebrow="PRODUCT / CHANGELOG" title="Verified release information belongs with the source." summary="This marketing-site repository does not contain a verified AgentOS release timeline. Rather than invent release notes, use the public repository and its release history for the current source of truth." primary={["View repository releases", `${github}/releases`, true]} secondary={["Open GitHub repository", github, true]} /><section className="page-pad empty-release"><span className="eyebrow">RELEASE INFORMATION</span><h2>No duplicate release feed on this site.</h2><p>AgentOS is actively developed. Version compatibility, installation details and update guidance should be taken from the repository and Quickstart that correspond to the version you are operating.</p><LinkRow links={[["AgentOS Quickstart", quickstart, true], ["Repository releases", `${github}/releases`, true], ["OpenClaw setup", "/openclaw-setup"]]} /></section><FinalCta title="Check compatibility before an update." copy="OpenClaw and AgentOS versions should be evaluated together, especially for a trusted runtime with persistent state." action={["Read the Quickstart", quickstart, true]} /></>; }

const desktopPlatforms = [
  { icon: "⌘", name: "macOS", packageName: "DMG installer", copy: "A native desktop shell for Apple Silicon and Intel Macs.", detail: "Use the latest release page for the published macOS build." },
  { icon: "⊞", name: "Windows", packageName: "Windows installer", copy: "Install AgentOS as a native Windows desktop application.", detail: "Use the latest release page for the published Windows build." },
  { icon: "◈", name: "Linux", packageName: "AppImage · DEB · RPM", copy: "Choose the Linux package that fits your desktop environment.", detail: "AppImage is the simplest starting point; package builds follow the release." },
] as const;

function DesktopDownload() {
  return <>
    <Hero eyebrow="PRODUCT / DESKTOP" title="AgentOS, installed on your desktop." summary="Run the AgentOS workspace as a native Tauri application on macOS, Windows and Linux. The desktop shell keeps the existing AgentOS product and OpenClaw runtime boundaries intact." image="/assets/screens/01-mission-control.webp" primary={["View latest release", desktopRelease, true]} secondary={["Deploy on Railway", deploy, true]} />
    <section className="page-pad desktop-release-banner">
      <div><span className="eyebrow">DESKTOP RELEASE CHANNEL</span><h2>One AgentOS experience across web and desktop.</h2><p>Desktop builds are published with the corresponding AgentOS release. Use the release page to find the installer for your platform as each signed build becomes available.</p></div>
      <External href={desktopRelease}><span className="button button--ghost">View release assets <b>↗</b></span></External>
    </section>
    <section className="page-pad desktop-download-section" aria-labelledby="desktop-download-title">
      <div className="section-heading"><span className="eyebrow">CHOOSE YOUR PLATFORM</span><h2 id="desktop-download-title">Download AgentOS Desktop.</h2><p>Install the native app, then connect the workspace, models and runtime you want to operate.</p></div>
      <div className="desktop-platform-grid">{desktopPlatforms.map((platform) => <article key={platform.name} className="desktop-platform-card"><div className="desktop-platform-icon" aria-hidden="true">{platform.icon}</div><div className="desktop-platform-card-copy"><span className="desktop-platform-package">{platform.packageName}</span><h3>{platform.name}</h3><p>{platform.copy}</p><small>{platform.detail}</small><External href={desktopRelease}><span className="button button--dark">View {platform.name} release <b>↗</b></span></External></div></article>)}</div>
      <p className="content-note">The release page is the source of truth for the current version and platform assets. Do not install unsigned or unofficial builds when operating a trusted workspace.</p>
    </section>
    <section className="page-pad desktop-runtime-section" aria-labelledby="desktop-runtime-title">
      <div className="section-heading"><span className="eyebrow">WHAT DESKTOP CHANGES</span><h2 id="desktop-runtime-title">A native shell around the AgentOS you already know.</h2></div>
      <div className="capability-list"><article><h3>Same AgentOS workspace</h3><p>Mission Control, workers, tasks and workspace context remain the product surface. Desktop does not introduce a second app or a separate data model.</p></article><article><h3>Packaged local server</h3><p>The desktop bundle starts the packaged AgentOS server on loopback and opens it in a native WebView.</p></article><article><h3>OpenClaw stays authoritative</h3><p>The desktop host owns the packaged AgentOS process; OpenClaw remains the runtime authority for execution, sessions, models and channels.</p></article></div>
    </section>
    <section className="page-pad desktop-install-steps" aria-labelledby="desktop-install-title">
      <div className="section-heading"><span className="eyebrow">GET STARTED</span><h2 id="desktop-install-title">From installer to first workspace.</h2></div>
      <ol><li><b>01</b><span><strong>Download</strong><small>Choose the current release for your operating system.</small></span></li><li><b>02</b><span><strong>Install</strong><small>Open the platform installer and launch AgentOS.</small></span></li><li><b>03</b><span><strong>Operate</strong><small>Connect a ready model and start with one reviewable task.</small></span></li></ol>
    </section>
    <FinalCta title="Prefer a hosted deployment?" copy="Use the published Railway path when you want AgentOS and its runtime in a persistent hosted environment." action={["Deploy on Railway", deploy, true]} />
  </>;
}

function ProductPage({ kind }: { kind: "product" | "features" }) { const features = [["Digital workers", "Create workers from presets or from scratch, then define identity, policies, model, heartbeat, file access and operating instructions."], ["Persistent workspaces", "Use project-backed workspaces for context, files, memory, tasks and the operating plan that connects them."], ["Tasks and operations", "Dispatch immediate, one-off, scheduled, interval or cron work where exposed by the connected OpenClaw runtime."], ["Runtime visibility", "Inspect health, compatibility, sessions, transcripts, output, warnings, token usage and created files without hiding degraded paths."], ["Models, channels and browser access", "Connect user-selected providers and work surfaces through OpenClaw. Actual availability depends on the configured runtime and scopes."], ["Human control", "Keep sensitive actions reviewable. Some approval-required access rules remain intentionally blocked until approval dispatch exists."]]; const title = kind === "product" ? "Build and operate a digital workforce from one human control surface." : "The operating capabilities behind a reviewable digital workforce."; const summary = kind === "product" ? "AgentOS organizes workers, workspaces, context, tasks, models and runtime visibility around the work a human team needs to supervise." : "AgentOS turns the underlying OpenClaw runtime into an operator experience for creating workers, assigning work, checking execution and keeping human judgment involved."; return <><Hero eyebrow={kind === "product" ? "PRODUCT / OVERVIEW" : "PRODUCT / FEATURES"} title={title} summary={summary} image="/assets/screens/01-mission-control.webp" primary={["Read the Quickstart", quickstart, true]} /><section className="page-pad capability-section"><div className="capability-list">{features.map(([title, text]) => <article key={title}><h3>{title}</h3><p>{text}</p></article>)}</div><LinkRow links={[["Explore templates", "/templates"], ["OpenClaw setup", "/openclaw-setup"], ["Read security", "/security"]]} /></section><FinalCta /> </>; }

export default function Subpage({ slug }: { slug: string }) { let body: React.ReactNode; if (solutionData[slug]) body = <Solutions data={solutionData[slug]} />; else if (slug === "docs") body = <Docs />; else if (slug === "deployment-guide") body = <DeploymentGuide />; else if (slug === "openclaw-setup") body = <OpenClawSetup />; else if (slug === "templates") body = <Templates />; else if (slug === "faq") body = <FAQ />; else if (slug === "support") body = <Support />; else if (slug === "about") body = <About />; else if (slug === "contact") body = <Contact />; else if (slug === "security") body = <Security />; else if (slug === "privacy" || slug === "terms") body = <Legal type={slug} />; else if (slug === "integrations") body = <Integrations />; else if (slug === "changelog") body = <Changelog />; else if (slug === "download") body = <DesktopDownload />; else body = <ProductPage kind={slug === "features" ? "features" : "product"} />; return <main><Header />{body}<Footer /></main>; }
